<script setup>
import {computed,onMounted,ref} from 'vue';import {pointageService} from '@/services/pointageService'
const d=new Date(),iso=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`,mode=ref('MOIS'),debut=ref(''),fin=ref(''),rows=ref([]),selected=ref(null),employee=ref(''),error=ref(''),loading=ref(false)
function period(){let y=d.getFullYear();if(mode.value==='JOUR')debut.value=fin.value=iso(d);else if(mode.value==='MOIS'){debut.value=`${y}-${String(d.getMonth()+1).padStart(2,'0')}-01`;fin.value=iso(new Date(y,d.getMonth()+1,0))}else if(mode.value==='ANNEE'){debut.value=`${y}-01-01`;fin.value=`${y}-12-31`}}
async function load(){loading.value=true;try{rows.value=await pointageService.dashboard(debut.value,fin.value)}catch(e){error.value=e.response?.data?.message||'Erreur'}finally{loading.value=false}}function change(){if(mode.value!=='DATES')period();load()}function mins(p){if(!p.entreeReelle||!p.sortieReelle)return 0;return Math.max(0,Math.round((new Date(p.sortieReelle)-new Date(p.entreeReelle))/60000))}function fmt(n){return `${Math.floor(n/60)}h ${String(n%60).padStart(2,'0')}min`}const employees=computed(()=>[...new Map(rows.value.filter(x=>x.employe).map(x=>[x.employe.id,x.employe])).values()]);const filtered=computed(()=>employee.value?rows.value.filter(x=>String(x.employe?.id)===String(employee.value)):rows.value);const totals=computed(()=>{let m=new Map();filtered.value.forEach(p=>{let id=p.employe?.id,x=m.get(id)||{employe:p.employe,jours:0,abs:0,retard:0,sup:0,trav:0};x.jours++;x.abs+=String(p.statut).toUpperCase()==='ABSENT'?1:0;x.retard+=p.minutesRetard||0;x.sup+=p.minutesHeuresSup||0;x.trav+=mins(p);m.set(id,x)});return [...m.values()]});const details=computed(()=>selected.value?rows.value.filter(p=>p.employe?.id===selected.value):[]);onMounted(()=>{period();load()})
</script>
<template><div class="container-fluid py-4"><h1 class="h3">{{selected?'Détail des pointages':'Synthèse des pointages'}}</h1><div class="card card-body mb-3"><div class="row g-2"><div class="col-md-3"><label class="form-label">Période</label><select v-model="mode" class="form-select" @change="change"><option value="JOUR">Journalière</option><option value="MOIS">Mensuelle</option><option value="ANNEE">Annuelle</option><option value="DATES">Dates personnalisées</option></select></div><div class="col-md-3"><label class="form-label">Début</label><input v-model="debut" type="date" class="form-control"></div><div class="col-md-3"><label class="form-label">Fin</label><input v-model="fin" type="date" class="form-control"></div><div class="col-md-3"><label class="form-label">Employé</label><select v-model="employee" class="form-select"><option value="">Tous</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.prenom}} {{e.nom}}</option></select></div></div><button class="btn btn-primary mt-3" @click="load">Actualiser</button></div><p v-if="error" class="alert alert-danger">{{error}}</p><button v-if="selected" class="btn btn-outline-secondary mb-3" @click="selected=null">← Retour à la synthèse</button><section class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr v-if="!selected"><th>Employé</th><th>Jours</th><th>Absences</th><th>Temps travaillé</th><th>Retards</th><th>Heures sup.</th></tr><tr v-else><th>Date</th><th>Entrée</th><th>Sortie</th><th>Temps travaillé</th><th>Retard</th><th>Heures sup.</th><th>Statut</th></tr></thead><tbody><tr v-if="!selected" v-for="s in totals" :key="s.employe?.id" @click="selected=s.employe.id" style="cursor:pointer"><td>{{s.employe?.prenom}} {{s.employe?.nom}}</td><td>{{s.jours}}</td><td>{{s.abs}}</td><td>{{fmt(s.trav)}}</td><td>{{s.retard}} min</td><td>{{s.sup}} min</td></tr><tr v-else v-for="p in details" :key="p.id"><td>{{p.datePointage}}</td><td>{{p.entreeReelle||'—'}}</td><td>{{p.sortieReelle||'—'}}</td><td>{{mins(p)?fmt(mins(p)):'—'}}</td><td>{{p.minutesRetard||0}} min</td><td>{{p.minutesHeuresSup||0}} min</td><td>{{p.statut}}</td></tr><tr v-if="!loading&&!((selected&&details.length)||(!selected&&totals.length))"><td colspan="7" class="text-center py-4">Aucune donnée.</td></tr></tbody></table></div></section></div></template>
